function VideoCard() {
  const isMobile = useIsMobile();
  const [muted, setMuted] = useState(true);
  const videoRef = useRef<HTMLVideoElement>(null);

  const toggleMute = () => {
    setMuted(prev => {
      const next = !prev;
      if (videoRef.current) videoRef.current.muted = next;
      return next;
    });
  };

  if (isMobile) {
    return (
      <div className="w-full relative">
        <video
          ref={videoRef}
          key="mobile"
          className="w-full h-auto block"
          src={welcomeVideoMobile}
          autoPlay
          loop
          playsInline
          muted
          preload="none"
        />
        <button
          onClick={toggleMute}
          aria-label={muted ? "Unmute video" : "Mute video"}
          className="absolute bottom-4 right-4 z-10 flex items-center gap-1.5 bg-black/40 hover:bg-black/60 backdrop-blur-sm text-white rounded-full px-3 py-1.5 text-xs font-medium transition-all duration-200"
        >
          {muted ? <VolumeX className="w-3.5 h-3.5" /> : <Volume2 className="w-3.5 h-3.5" />}
          {muted ? "Unmute" : "Mute"}
        </button>
      </div>
    );
  }

  return (
    <div className="h-full w-full relative overflow-hidden">
      <video
        ref={videoRef}
        key="desktop"
        className="absolute inset-0 w-full h-full object-cover"
        src={welcomeVideo}
        autoPlay
        loop
        playsInline
        muted
        preload="none"
      />
